require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../database/conexao.php';exigirLogin();
$tituloPagina='Relatórios';$pdo=conectar();$usuarioId=usuarioLogadoId();$empreendedor=usuarioLogadoTipo()==='mei';$periodo=(int)($_GET['periodo']??1);if(!in_array($periodo,[1,3,6,12],true))$periodo=1;$inicio=date('Y-m-01',strtotime('-'.($periodo-1).' months'));$fim=date('Y-m-t');
function executarPythonRel(string $script,array $args):?array{$pasta=escapeshellarg(__DIR__.'/../python');$python=PHP_OS_FAMILY==='Windows'?'python':'python3';$cmd='cd '.$pasta.' && '.$python.' '.escapeshellarg($script);foreach($args as $a)$cmd.=' '.escapeshellarg((string)$a);$cmd.=' 2>/dev/null';$saida=@shell_exec($cmd);$d=json_decode($saida??'',true);return is_array($d)?$d:null;}
$res=executarPythonRel('analise.py',[$usuarioId,$periodo]);$evolucaoMensal=$res['evolucao_mensal']??[];
if(empty($evolucaoMensal)){for($i=$periodo-1;$i>=0;$i--){$ref=new DateTime("first day of -{$i} month");$ri=$ref->format('Y-m-01');$rf=$ref->format('Y-m-t');$a=$pdo->prepare('SELECT COALESCE(SUM(valor),0) FROM receitas WHERE usuario_id=:uid AND data_receita BETWEEN :i AND :f');$a->execute(['uid'=>$usuarioId,'i'=>$ri,'f'=>$rf]);$r=(float)$a->fetchColumn();$a=$pdo->prepare('SELECT COALESCE(SUM(valor),0) FROM despesas WHERE usuario_id=:uid AND data_despesa BETWEEN :i AND :f');$a->execute(['uid'=>$usuarioId,'i'=>$ri,'f'=>$rf]);$d=(float)$a->fetchColumn();$evolucaoMensal[]=['mes'=>$ref->format('Y-m'),'receitas'=>$r,'despesas'=>$d];}}
function categoriasRel(PDO $pdo,string $tabela,string $campo,int $uid,string $i,string $f):array{$s=$pdo->prepare("SELECT COALESCE(c.nome,'Outros') categoria,COALESCE(SUM(x.valor),0) total FROM {$tabela} x LEFT JOIN categorias c ON c.id=x.categoria_id WHERE x.usuario_id=:uid AND x.{$campo} BETWEEN :i AND :f GROUP BY categoria ORDER BY total DESC");$s->execute(['uid'=>$uid,'i'=>$i,'f'=>$f]);return $s->fetchAll();}
$gastos=categoriasRel($pdo,'despesas','data_despesa',$usuarioId,$inicio,$fim);$entradas=categoriasRel($pdo,'receitas','data_receita',$usuarioId,$inicio,$fim);$receitasPeriodo=array_sum(array_map('floatval',array_column($entradas,'total')));$despesasPeriodo=array_sum(array_map('floatval',array_column($gastos,'total')));$maiorCategoria=$gastos[0]??null;$origemRenda=$entradas[0]??null;$resultado=$receitasPeriodo-$despesasPeriodo;
$stmt=$pdo->prepare('SELECT descricao,SUM(valor) total,COUNT(*) ocorrencias FROM despesas WHERE usuario_id=:uid AND data_despesa>=:inicio GROUP BY descricao HAVING COUNT(*)>=2 ORDER BY total DESC LIMIT 1');$stmt->execute(['uid'=>$usuarioId,'inicio'=>$inicio]);$gastoRecorrente=$stmt->fetch();
$leitura=[];$leitura[]=$resultado>=0?'O período terminou com resultado positivo de '.formatarMoeda($resultado).'.':'O período terminou com resultado negativo de '.formatarMoeda(abs($resultado)).'.';if($maiorCategoria&&$despesasPeriodo>0){$pct=((float)$maiorCategoria['total']/$despesasPeriodo)*100;$leitura[]=$maiorCategoria['categoria'].' concentra '.number_format($pct,1,',','.').'% das despesas do período.';}if($origemRenda&&$receitasPeriodo>0){$pct=((float)$origemRenda['total']/$receitasPeriodo)*100;$leitura[]=$origemRenda['categoria'].' representa '.number_format($pct,1,',','.').'% das entradas.';}
?>
