<div class="grade-resumo"><div class="cartao cartao-metrica"><div class="rotulo"><?= $empreendedor ? 'Maior origem de faturamento' : 'Maior origem de renda' ?></div><div class="valor positivo" style="font-size:20px"><?=limpar($origemRenda['categoria']??'Sem dados')?></div><?php if($origemRenda):?><div class="variacao"><?=formatarMoeda((float)$origemRenda['total'])?> no período</div><?php endif;?></div><div class="cartao cartao-metrica"><div class="rotulo">Maior categoria de gasto</div><div class="valor negativo" style="font-size:20px"><?=limpar($maiorCategoria['categoria']??'Sem dados')?></div><?php if($maiorCategoria):?><div class="variacao"><?=formatarMoeda((float)$maiorCategoria['total'])?> no período</div><?php endif;?></div><div class="cartao cartao-metrica"><div class="rotulo">Gasto recorrente</div><div class="valor negativo" style="font-size:20px"><?=limpar($gastoRecorrente['descricao']??'Nenhum identificado')?></div><?php if($gastoRecorrente):?><div class="variacao"><?=(int)$gastoRecorrente['ocorrencias']?> ocorrências · <?=formatarMoeda((float)$gastoRecorrente['total'])?></div><?php endif;?></div></div>
<div class="grade-dupla"><div class="cartao"><div class="cabecalho-grafico"><div><h3><?= $empreendedor ? 'Faturamento x Despesas' : 'Receitas x Despesas' ?></h3><p class="secao-ajuda">Evolução do período selecionado.</p></div></div><div class="container-grafico"><canvas id="graficoEvolucaoRelatorio"></canvas></div></div><div class="cartao"><div class="cabecalho-grafico"><div><h3>Distribuição</h3><p class="secao-ajuda">Escolha se quer analisar entradas ou gastos.</p></div><div class="periodos-grafico"><button type="button" class="rel-tipo ativo" data-tipo="gastos">Gastos</button><button type="button" class="rel-tipo" data-tipo="entradas">Entradas</button></div></div><div class="container-grafico" style="height:260px"><canvas id="graficoCategorias"></canvas></div></div></div>
<div class="grade-dupla" style="margin-top:20px"><div class="cartao"><h3 style="margin-bottom:16px">Detalhamento</h3><div class="rel-detalhes" id="relDetalhes"></div></div><div class="cartao"><div class="radar-titulo"><div><h3>O que esses dados mostram?</h3><p class="secao-ajuda">Uma leitura rápida antes de aprofundar a análise.</p></div><button type="button" class="btn btn-secundario" data-copiloto-pergunta="Explique meu relatório dos últimos <?=$periodo?> mês(es) e indique o ponto que mais merece atenção.">Perguntar ao Copiloto</button></div><div class="rel-leitura"><?php foreach($leitura as $linha):?><p>• <?=limpar($linha)?></p><?php endforeach;?></div></div></div>
<script src="../assets/js/dashboard.js"></script><script src="../assets/js/relatorios.js"></script><script>const dadosEvolucao=<?=json_encode($evolucaoMensal,JSON_UNESCAPED_UNICODE)?>;const dadosGastos=<?=json_encode($gastos,JSON_UNESCAPED_UNICODE)?>;const dadosEntradas=<?=json_encode($entradas,JSON_UNESCAPED_UNICODE)?>;inicializarGraficoEvolucao(dadosEvolucao,'graficoEvolucaoRelatorio');inicializarGraficoCategorias(dadosGastos);inicializarRelatorioAlternancia(dadosGastos,dadosEntradas);</script>
